package com.hs.jxc.pur;

import static com.hs.jxc.pur.PurchaseImportService.*;
import com.hs.jxc.attachment.*;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.db.DbContext;
import com.hs.jxc.common.idempotency.IdempotencyExecutor;
import com.hs.jxc.sys.api.Access;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/** 持久租约只围绕短事务；网络、原图写入均发生在事务外。 */
@Service
public class PurchaseImportTaskService {
    private final PurchaseImportService imports;private final PurchaseImportRecognitionClient parser;
    private final AttachmentAssetService assets;private final JdbcTemplate jdbc;private final DbContext db;private final IdempotencyExecutor commands;
    record Lease(UUID id,long country,UUID batch,long source,int revision,UUID owner,RequestContext actor,String token,String sha,String sheet){}
    public PurchaseImportTaskService(PurchaseImportService imports,PurchaseImportRecognitionClient parser,AttachmentAssetService assets,JdbcTemplate jdbc,DbContext db,IdempotencyExecutor commands){this.imports=imports;this.parser=parser;this.assets=assets;this.jdbc=jdbc;this.db=db;this.commands=commands;}
    private void gates(long country){db.apply(null);imports.auth.gate(0,false);db.apply(country);imports.auth.gate(country,false);}
    RequestContext actor(Map<String,Object> t){var basis=imports.map(t.get("authorization_basis"));return new RequestContext(number(t,"requested_by"),number(t,"country_id"),"purchase-task-"+t.get("id"),basis.get("tokenHash").toString());}
    private Lease claim(long country,UUID id){return imports.tx.execute(s->{
        gates(country);var found=jdbc.queryForList("SELECT * FROM pur_order_import_task WHERE country_id=? AND id=? AND (status='QUEUED' OR status='RUNNING' AND lease_until<clock_timestamp())",country,id);if(found.isEmpty())return null;
        // 领取、完成、编辑和重试统一先锁批次，再锁任务，避免恢复竞争时逆序锁定。
        jdbc.queryForList("SELECT batch_id FROM pur_order_import_batch WHERE country_id=? AND batch_id=? FOR UPDATE",country,found.getFirst().get("batch_id"));
        found=jdbc.queryForList("SELECT * FROM pur_order_import_task WHERE country_id=? AND id=? AND (status='QUEUED' OR status='RUNNING' AND lease_until<clock_timestamp()) FOR UPDATE SKIP LOCKED",country,id);if(found.isEmpty())return null;var task=found.getFirst();var ctx=actor(task);Access a;
        try{a=imports.access(ctx,true);imports.batch(a,(UUID)task.get("batch_id"),false);}catch(ApiException e){jdbc.update("UPDATE pur_order_import_task SET status='NEEDS_REAUTH',error_code=?,error_message=?,credential_hash=NULL,updated_at=clock_timestamp() WHERE country_id=? AND id=?",e.getCode(),"请求者授权已失效，请重新登录后重试",country,id);return null;}
        UUID batch=(UUID)task.get("batch_id");var b=imports.batch(a,batch,true);if(number(b,"version")!=number(task,"input_revision")){jdbc.update("UPDATE pur_order_import_task SET status='STALE',error_code='INPUT_CHANGED',error_message='批次内容已变化，请确认后重试',credential_hash=NULL WHERE country_id=? AND id=?",country,id);return null;}
        String token=country+":"+UUID.randomUUID()+UUID.randomUUID().toString();UUID lease=UUID.randomUUID();
        jdbc.update("UPDATE pur_order_import_task SET status='RUNNING',attempt_count=attempt_count+1,lease_owner=?,lease_until=clock_timestamp()+interval '15 minutes',expires_at=clock_timestamp()+interval '15 minutes',credential_hash=?,error_code=NULL,error_message=NULL,updated_at=clock_timestamp() WHERE country_id=? AND id=?",lease,hash(token),country,id);
        jdbc.update("UPDATE pur_order_import_source SET status='PARSING',error_code=NULL,error_message=NULL WHERE country_id=? AND id=?",country,task.get("source_id"));
        var options=imports.map(jdbc.queryForObject("SELECT parse_options FROM pur_order_import_source WHERE country_id=? AND id=?",Object.class,country,task.get("source_id")));
        return new Lease(id,country,batch,number(task,"source_id"),(int)number(task,"input_revision"),lease,ctx,token,task.get("input_hash").toString(),(String)options.get("sheet"));
    });}
    public void execute(long country,UUID taskId){
        Lease lease=claim(country,taskId);if(lease==null)return;
        try{
            var result=parser.parse(taskId,lease.token,lease.source,lease.sha,lease.sheet);validate(result,lease.sha);
            var prepared=new LinkedHashMap<String,AttachmentAssetService.Prepared>();
            for(var image:list(result.get("images"))){byte[] content;try{content=Base64.getDecoder().decode(Inputs.required(image,"contentBase64"));}catch(IllegalArgumentException e){throw Inputs.bad("解析图片编码无效");}
                String sha=Inputs.required(image,"sha256"),mime=Inputs.required(image,"mimeType");if(!Set.of("image/png","image/jpeg","image/webp","image/gif").contains(mime)||!sha.equals(AttachmentObjectStore.sha256(content))||content.length!=number(image,"bytes"))throw Inputs.bad("原图哈希、格式或大小不一致");
                if(prepared.put(Inputs.required(image,"imageId"),assets.prepare(lease.actor,AttachmentAssetService.Policy.PURCHASE_IMAGE,sha+".image",mime,content))!=null)throw Inputs.bad("原图编号重复");
            }
            imports.tx.execute(s->{Access a=imports.access(lease.actor,true);var b=imports.batch(a,lease.batch,true);var task=active(lease);
                if(number(b,"version")!=lease.revision)throw new ApiException(409,"INPUT_CHANGED","批次内容已变化，解析结果未写入");
                int next=(int)number(b,"next_row_no");var h=imports.map(b.get("header"));var rowIds=new HashMap<String,Long>();var imageIds=new HashMap<String,Long>();
                for(var image:list(result.get("images"))){String imageKey=Inputs.required(image,"imageId");long asset=assets.register(lease.actor,prepared.get(imageKey));long id=jdbc.queryForObject("INSERT INTO pur_order_import_image(country_id,source_id,attachment_id,image_sha256,media_part,mime_type,width,height) VALUES(?,?,?,?,?,?,?,?) RETURNING id",Long.class,country,lease.source,asset,image.get("sha256"),image.get("mediaPart"),image.get("mimeType"),Inputs.id(image.get("width")),Inputs.id(image.get("height")));imageIds.put(imageKey,id);}
                for(var row:list(result.get("rows"))){var values=values(imports.map(row.get("normalizedValues")));var args=new ArrayList<Object>(List.of(country,lease.batch,next++,h.get("bookId"),h.get("supplierId"),h.get("currency"),h.get("orderDate")));args.add(h.get("expectedDate"));args.add(h.get("paymentTerms"));args.add(h.get("prepayRatio"));args.add(h.get("termDays"));FIELDS.forEach(k->args.add(values.get(k)));args.add(lease.actor.userId());args.add(lease.source);args.add(row.get("sourceSheet"));args.add(Inputs.id(row.get("sourceRow")));args.add(imports.json.write(imports.map(row.get("originalValues"))));args.add(imports.json.write(Map.of("formulas",imports.map(row.get("formulas")),"rawNumericTexts",imports.map(row.get("rawNumericTexts")),"cachedValues",imports.map(row.get("cachedValues")),"valuesRecalculated",false)));var origins=new LinkedHashMap<String,Object>();FIELDS.forEach(k->origins.put(k,"FILE"));args.add(imports.json.write(origins));
                    long id=jdbc.queryForObject("INSERT INTO pur_order_import(country_id,batch_id,row_no,book_id,supplier_id,currency,order_date,expected_date,payment_terms,prepay_ratio,term_days,"+String.join(",",COLUMNS)+",created_by,source_id,source_sheet,source_row,original_values,formula_provenance,field_origins) VALUES(?,?,?,?,?,?,?::date,?::date,?,?::numeric,?,"+String.join(",",Collections.nCopies(FIELDS.size(),"?"))+",?,?,?,?,?::jsonb,?::jsonb,?::jsonb) RETURNING id",Long.class,args.toArray());rowIds.put(row.get("sourceSheet")+":"+row.get("sourceRow"),id);
                }
                for(var assoc:list(result.get("associations"))){Long row=rowIds.get(assoc.get("sourceSheet")+":"+assoc.get("sourceRow"));Long image=imageIds.get(assoc.get("imageId"));if(image==null)throw Inputs.bad("图片锚点引用不存在的图片");if(row!=null)jdbc.update("INSERT INTO pur_order_import_row_image(country_id,row_id,image_id,anchor) VALUES(?,?,?,?::jsonb) ON CONFLICT(country_id,row_id,image_id) DO UPDATE SET anchor=pur_order_import_row_image.anchor||excluded.anchor",country,row,image,imports.json.write(Map.of("anchors",List.of(assoc.get("anchor")))));}
                jdbc.update("UPDATE pur_order_import_source SET status='READY',parser_version=?,sheets=?::jsonb,warnings=?::jsonb,associations=?::jsonb,error_code=NULL,error_message=NULL WHERE country_id=? AND id=?",imports.map(result.get("source")).get("parserVersion"),imports.json.write(result.get("sheets")),imports.json.write(result.get("warnings")),imports.json.write(result.get("associations")),country,lease.source);
                jdbc.update("UPDATE pur_order_import_batch SET status='REVIEW',next_row_no=?,version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND batch_id=?",next,country,lease.batch);
                jdbc.update("UPDATE pur_order_import_task SET status='SUCCEEDED',result=?::jsonb,credential_hash=NULL,lease_owner=NULL,lease_until=NULL,updated_at=clock_timestamp() WHERE country_id=? AND id=?",imports.json.write(Map.of("sourceId",lease.source,"rows",rowIds.size(),"images",imageIds.size())),country,taskId);return null;
            });
        }catch(RuntimeException error){String code=error instanceof ApiException api?api.getCode():"PARSE_FAILED";String message=error instanceof ApiException api?api.getMessage():"解析或持久化失败，请检查服务后重试";
            imports.tx.execute(s->{gates(country);String state=code.equals("INPUT_CHANGED")?"STALE":code.startsWith("AUTH_")||code.equals("SYS_FORBIDDEN")?"NEEDS_REAUTH":"FAILED";Object details=error instanceof ApiException api?api.getData():null;
                int changed=jdbc.update("UPDATE pur_order_import_task SET status=?,error_code=?,error_message=?,result=?::jsonb,credential_hash=NULL,lease_until=NULL,lease_owner=NULL,updated_at=clock_timestamp() WHERE country_id=? AND id=? AND lease_owner=? AND status='RUNNING'",state,code,message,details==null?null:imports.json.write(details),country,taskId,lease.owner);
                if(changed==1){jdbc.update("UPDATE pur_order_import_source SET status=?,error_code=?,error_message=? WHERE country_id=? AND id=?",state.equals("STALE")?"STALE":"FAILED",code,message,country,lease.source);jdbc.update("UPDATE pur_order_import_batch SET status='FAILED' WHERE country_id=? AND batch_id=?",country,lease.batch);}return null;
            });
        }
    }
    private Map<String,Object> active(Lease lease){var found=jdbc.queryForList("SELECT * FROM pur_order_import_task WHERE country_id=? AND id=? AND lease_owner=? AND status='RUNNING' AND lease_until>clock_timestamp() FOR UPDATE",lease.country,lease.id,lease.owner);if(found.size()!=1)throw new ApiException(409,"TASK_LEASE_LOST","任务租约已失效，旧结果未写入");return found.getFirst();}
    private void validate(Map<String,Object> result,String sha){if(!"SourceDocumentV1".equals(result.get("format"))||!sha.equals(imports.map(result.get("source")).get("fileSha256")))throw Inputs.bad("解析来源合同或文件哈希不一致");Inputs.required(imports.map(result.get("source")),"parserVersion");if(!list(result.get("errors")).isEmpty())throw Inputs.bad("解析来源含错误，未保存采购明细");var rows=list(result.get("rows"));if(rows.isEmpty()||rows.size()>10000)throw Inputs.bad("采购明细为空或超过10000行");var selected=list(result.get("sheets")).stream().filter(s->"PURCHASE".equals(s.get("role"))).toList();if(selected.size()!=1)throw Inputs.bad("必须选择唯一采购工作表");Set<String> positions=new HashSet<>();for(var row:rows){if(!Objects.equals(row.get("sourceSheet"),selected.getFirst().get("name"))||!positions.add(row.get("sourceSheet")+":"+Inputs.id(row.get("sourceRow"))))throw Inputs.bad("采购行来源重复或混入其他工作表");values(imports.map(row.get("normalizedValues")));for(String field:List.of("originalValues","formulas","rawNumericTexts","cachedValues"))imports.map(row.get(field));}list(result.get("images"));list(result.get("associations"));list(result.get("warnings"));}
    public Map<String,Object> get(RequestContext ctx,UUID id){return imports.tx.execute(s->{Access a=imports.access(ctx,false);var rows=jdbc.queryForList("SELECT * FROM pur_order_import_task WHERE country_id=? AND id=?",a.requireCountry(),id);if(rows.size()!=1)throw ApiException.notFound();imports.batch(a,(UUID)rows.getFirst().get("batch_id"),false);return imports.taskDto(rows.getFirst());});}
    public Map<String,Object> retry(RequestContext ctx,UUID id,String key,String sheet){return imports.tx.execute(s->{Access a=imports.access(ctx,true);var rows=jdbc.queryForList("SELECT * FROM pur_order_import_task WHERE country_id=? AND id=?",a.requireCountry(),id);if(rows.size()!=1)throw ApiException.notFound();var task=rows.getFirst();var b=imports.batch(a,(UUID)task.get("batch_id"),true);var lockedTask=jdbc.queryForMap("SELECT * FROM pur_order_import_task WHERE country_id=? AND id=? FOR UPDATE",a.requireCountry(),id);var request=new LinkedHashMap<String,Object>();request.put("sheet",sheet);return commands.execute(ctx,"POST",BASE+"/tasks/"+id+"/retry",key,request,Inputs.id(imports.map(b.get("header")).get("bookId")),()->{if(!Set.of("FAILED","NEEDS_REAUTH","STALE").contains(lockedTask.get("status")))throw Inputs.conflict();jdbc.update("UPDATE pur_order_import_task SET status='QUEUED',input_revision=?,authorization_basis=?::jsonb,requested_by=?,error_code=NULL,error_message=NULL,result=NULL,credential_hash=NULL,expires_at=clock_timestamp()+interval '1 hour',updated_at=clock_timestamp() WHERE country_id=? AND id=?",b.get("version"),imports.json.write(Map.of("userId",ctx.userId(),"tokenHash",ctx.tokenHash())),ctx.userId(),a.requireCountry(),id);var options=new LinkedHashMap<String,Object>();if(sheet!=null)options.put("sheet",sheet);jdbc.update("UPDATE pur_order_import_source SET status='PENDING',parse_options=?::jsonb WHERE country_id=? AND id=?",imports.json.write(options),a.requireCountry(),task.get("source_id"));jdbc.update("UPDATE pur_order_import_batch SET status='PARSING' WHERE country_id=? AND batch_id=?",a.requireCountry(),task.get("batch_id"));return Map.of("id",id.toString(),"status","QUEUED");},r->imports.batch(a,(UUID)task.get("batch_id"),false));});}
    public int recover(long country,int limit){var ids=imports.tx.execute(s->{gates(country);return jdbc.queryForList("SELECT id FROM pur_order_import_task WHERE country_id=? AND kind='PARSE' AND (status='QUEUED' OR status='RUNNING' AND lease_until<clock_timestamp()) ORDER BY created_at LIMIT ?",UUID.class,country,limit);});ids.forEach(id->execute(country,id));return ids.size();}
    public AttachmentService.Download taskAsset(UUID taskId,long sourceId,String token){
        long country;try{country=Long.parseLong(token.substring(0,token.indexOf(':')));if(country<=0)throw new IllegalArgumentException();}catch(RuntimeException e){throw ApiException.forbidden();}
        RequestContext ctx=imports.tx.execute(s->{gates(country);var rows=jdbc.queryForList("SELECT * FROM pur_order_import_task WHERE country_id=? AND id=? AND source_id=? AND status='RUNNING' AND expires_at>clock_timestamp() AND lease_until>clock_timestamp()",country,taskId,sourceId);if(rows.size()!=1||!java.security.MessageDigest.isEqual(hash(token).getBytes(StandardCharsets.US_ASCII),Objects.toString(rows.getFirst().get("credential_hash"),"").getBytes(StandardCharsets.US_ASCII)))throw ApiException.forbidden();return actor(rows.getFirst());});
        UUID batch=imports.tx.execute(s->{imports.access(ctx,false);return jdbc.queryForObject("SELECT batch_id FROM pur_order_import_task WHERE country_id=? AND id=?",UUID.class,country,taskId);});return imports.content(ctx,batch,sourceId,false);
    }
    private static String hash(String value){return AttachmentObjectStore.sha256(value.getBytes(StandardCharsets.UTF_8));}
}
